using System.ComponentModel.DataAnnotations;

namespace SecureHomeSystem.Configuration;

/// <summary>
/// Defines retention limits for service log files generated by
/// <see cref="Services.ContainerLogCollector" />. Thresholds are optional—set
/// them to zero to disable a specific limit.
/// </summary>
public sealed class LogRotationOptions
{
    /// <summary>
    /// Maximum size (in bytes) for the active log file before it is rotated.
    /// </summary>
    [Range(0, long.MaxValue)]
    public long MaxFileSizeBytes { get; set; } = 10 * 1024 * 1024;

    /// <summary>
    /// Maximum age (in days) for the active log file before it is rotated.
    /// </summary>
    [Range(0, int.MaxValue)]
    public int MaxFileAgeDays { get; set; } = 7;

    /// <summary>
    /// Maximum number of rotated archives to keep per service. Newer files are
    /// retained first. Set to zero to disable pruning by count.
    /// </summary>
    [Range(0, int.MaxValue)]
    public int MaxArchiveFiles { get; set; } = 5;
}
